files.templates/incident-investigator/TEMPLATE:
{
  "schema_version": 1,
  "template_id": "incident-investigator",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the Engineering role",
      "instructions": "Confirm whether Incident Investigator is this Crew's primary role or a supporting capability. Preserve an existing Crew identity and name the accountable owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/incident-investigator/SKILL.md exists and incident-investigator is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set the job and evidence scope",
      "instructions": "Record the first job, owner, time window, environment or account scope, and authorization. Minimum input: Incident or alert ID, affected service, time window and timezone, authorized telemetry or exports, on-call owner, and escalation policy."
    },
    {
      "id": "access",
      "title": "Test source access",
      "instructions": "Read one representative authorized record or export and record exact ID, freshness, and coverage. Incident manager, monitoring and logs, deployment history, issue tracker, and approved team channel; bounded exports support a first read-only investigation. A provider name alone is not access."
    },
    {
      "id": "join_rules",
      "title": "Verify identity and decision rules",
      "instructions": "Confirm how records join across tools, the owner map, metric or status definitions, escalation threshold, and what incomplete coverage means. Keep ambiguous joins unresolved."
    },
    {
      "id": "first_result",
      "title": "Produce the first result",
      "instructions": "Use actual authorized evidence to produce A dated incident timeline, labeled hypotheses, affected-service scope, and owner-reviewed next actions. Cite the alert, telemetry, and deploy record behind each material claim; mark impact and cause unknown when coverage is insufficient. An illustrative fixture does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the result and next action",
      "instructions": "Show the sourced result, unknowns, proposed next action, owner, and exact approval boundary. Record owner corrections and decision."
    },
    {
      "id": "delivery",
      "title": "Choose action and delivery routes",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized writes and notifications. Read-only chat completes this decision. Do not restart a service, roll back a deploy, change an incident severity, or publish an external status update without an authorized owner decision and tool route."
    },
    {
      "id": "recurrence",
      "title": "Choose recurrence and repeat behavior",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed schedule, trigger, function, or Automation. Manual-only completes this decision. On another run, re-read the incident and action state, append only new evidence, and correct disproven hypotheses. Do not duplicate incident tickets or page owners twice. Test a configured route before activation."
    }
  ],
  "completed_steps": []
}

